import unittest

from csv_import import tags_from_csv
from form_import import tags_from_form
from normalise import clean_token


class CleanTokenTests(unittest.TestCase):
    def test_trims_and_lowercases(self):
        self.assertEqual(clean_token("  Urgent  "), "urgent")

    def test_drops_trailing_separator(self):
        self.assertEqual(clean_token("urgent,"), "urgent")

    def test_drops_separator_outside_whitespace(self):
        # "urgent ," -> the comma is last, the space is inside.
        self.assertEqual(clean_token("urgent ,"), "urgent")

    def test_drops_separator_inside_whitespace(self):
        # " ,urgent " -> the comma is inside the whitespace, not outside it.
        self.assertEqual(clean_token(" , urgent , "), "urgent")

    def test_separator_only_token_becomes_empty(self):
        self.assertEqual(clean_token(","), "")

    def test_keeps_internal_punctuation(self):
        self.assertEqual(clean_token("Front-End"), "front-end")


class FormImportTests(unittest.TestCase):
    def test_user_typed_commas_are_not_part_of_the_tag(self):
        self.assertEqual(tags_from_form("urgent, billing"), ["urgent", "billing"])

    def test_detached_commas_do_not_become_tags(self):
        self.assertEqual(tags_from_form("Urgent , billing ,"), ["urgent", "billing"])


class CsvImportTests(unittest.TestCase):
    def test_trailing_comma_on_line(self):
        self.assertEqual(tags_from_csv("urgent, billing,"), ["urgent", "billing"])

    def test_quoted_field_leaves_no_empty_tags(self):
        self.assertEqual(tags_from_csv("urgent, , billing"), ["urgent", "billing"])


if __name__ == "__main__":
    unittest.main(verbosity=2)

